<?php require_once __DIR__.'/../config/db.php';require_once __DIR__.'/../services/userService.php';require_once __DIR__.'/../includes/auth.php';$pdo=openDatabase();$user=requireLogin($pdo);$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrfToken($_POST);try{$user=saveOwnProfile($pdo,(int)$user['user_id'],$_POST);$_SESSION['display_name']=$user['full_name'];$message='Profile updated.';}catch(InvalidArgumentException $e){$error=$e->getMessage();}}require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/nav.php';?><main class="container py-4"><h1>Edit profile</h1><?php if($error):?><div class="alert alert-danger"><?=htmlspecialchars($error,ENT_QUOTES,'UTF-8')?></div><?php endif;?><?php if(!empty($message)):?><div class="alert alert-success"><?=$message?></div><?php endif;?><form method="post"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(csrfToken(),ENT_QUOTES,'UTF-8')?>"><label>Name<input class="form-control" name="full_name" value="<?=htmlspecialchars($user['full_name'],ENT_QUOTES,'UTF-8')?>" required></label><label>Email<input class="form-control" type="email" name="email" value="<?=htmlspecialchars($user['email'],ENT_QUOTES,'UTF-8')?>" required></label><button class="btn btn-primary">Save changes</button></form></main><?php require __DIR__.'/../includes/footer.php';?>
